        />
      </div>
        <!-- <div class="name">{{ header }}</div> -->
        
        <q-card-section class="acct-section">
          <div class="label">บัญชีหลัก</div>
          <div class="amt">{{ mainWallet}}</div>
        </q-card-section>
        <q-separator vertical />
      </q-card-section>
    </div>
    <q-card-actions style="display:flex;">
      <q-btn color="positive" class="q-pa-lg" style="flex:1; border-radius: 10px;" @click="openDeposit" no-caps
        ><RiWalletLine />ฝาก</q-btn
      >
      <q-btn color="negative" class="q-pa-lg" to="finance/withdraw" style="flex:1; border-radius: 10px;" no-caps
        ><RiBankCardLine />ถอน</q-btn
      >
    </q-card-actions>
    <q-item-section class="acct-nav">
      <router-link to="/account/transit">
        <q-card class="acct-nav-item">
          <RiShieldFlashLine />
          <div class="acct-nav-label">บันทึกการโอน</div>
        </q-card>
      </router-link>
      <router-link to="/account/personal">
        <q-card class="acct-nav-item">
          <RiUser5Line />
          <div class="acct-nav-label"> ข้อมูลส่วนตัว </div>
        </q-card>
      </router-link>
      <router-link to="/account/withdraw">
        <q-card class="acct-nav-item">
          <RiBankLine />
          <div class="acct-nav-label"> ถอนไปยังบัญชีธนาคาร </div>
        </q-card>
      </router-link>

      <router-link to="/account/mail">
        <q-card class="acct-nav-item">
          <RiMailLine />
          <div class="acct-nav-label"> กล่องจดหมาย </div>
        </q-card>
      </router-link>
      <router-link to="/affiliate">
        <q-card class="acct-nav-item">
          <RiTeamLine />
          <div class="acct-nav-label">บริษัทในเครือ</div>
        </q-card>
      </router-link>
      <router-link to="/vip">
        <q-card class="acct-nav-item">
          <RiVipCrown2Line />
          <div class="acct-nav-label">VIP</div>
        </q-card>
      </router-link>
      <router-link to="/share">
        <q-card class="acct-nav-item">
          <RiShareBoxLine />
          <div class="acct-nav-label">แชร์</div>
        </q-card>
      </router-link>
      <a @click="logout">
        <q-card class="acct-nav-item">
          <RiLogoutBoxLine />
          <div class="acct-nav-label">ล็อกเอ้าท์</div>
        </q-card>
      </a>
    </q-item-section>
  </q-page>
</template>

<script>
import { defineComponent, ref, computed, onMounted } from "vue";
import { userStore } from "stores/index";
import {
  RiWalletLine,
  RiBankCardLine,
  RiShieldFlashLine,
  RiUser5Line,
  RiBankLine,
  RiMailLine,
  RiVipCrown2Line,
  RiShareBoxLine,
  RiTeamLine,
  RiLogoutBoxLine
} from "vue-remix-icons";
import {useRouter} from "vue-router";

export default defineComponent({
  name: "AccountPage",
  components: {
    RiWalletLine,
    RiBankCardLine,
    RiShieldFlashLine,
    RiUser5Line,
    RiBankLine,
    RiMailLine,
    RiVipCrown2Line,
    RiShareBoxLine,
    RiTeamLine,
    RiLogoutBoxLine
  },
  setup() {
    const router= useRouter();
    const store = userStore();
    const logout = () => {
      store.memberLogout().then(() => {
        location.reload();
      });
    };

    const vip = computed(() => {
      return store.vip;
    });

    const mainWallet = computed(() => {
      return store.currency.value + ' ' + store.balance;
    });
    onMounted(() => {
      getBalance()
      store.getBalance()
    });

    const openDeposit = () => {
      // to="finance/deposit"
      localStorage.setItem("isOpenFromAccount", JSON.stringify(true));
      router.push('finance/deposit');
    }

    const getBalance = () => {
        setInterval(function(){ if (store.hasToken()) { store.getBalance() } }, 20000);
    }
    return {
      header: "บัญชี",
      logout,
      mainWallet,
      getBalance,
      vip,
      openDeposit
    };
  }
});
</script>
